    if idx < 0:
        raise SystemExit("Could not find ## 2026-10-08 marker")
    new_text = text[:idx] + NEW_TREND_INDEX_SECTION + text[idx:]
    p.write_text(new_text, encoding="utf-8")
    print("Prepended 2026-10-09 section to trend-index.md")